{"implementation": "def solve(case):
    threshold = case["threshold"]
    calls = case["calls"]
    if not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be numeric")
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")
    diagnostics = []
    accepted_call_ids = []
    for call in calls:
        for field in ("call_id", "loss_without_call", "loss_with_call", "prediction_tokens", "parseable"):
            if field not in call:
                raise ValueError(f"Missing required field {field!r} in call")
        call_id = call["call_id"]
        loss_without = call["loss_without_call"]
        loss_with = call["loss_with_call"]
        prediction_tokens = call["prediction_tokens"]
        parseable = call["parseable"]
        if not isinstance(prediction_tokens, int) or prediction_tokens < 1:
            raise ValueError(f"prediction_tokens must be a positive integer for call {call_id!r}")
        if not isinstance(loss_without, (int, float)):
            raise ValueError(f"loss_without_call must be numeric for call {call_id!r}")
        if not isinstance(loss_with, (int, float)):
            raise ValueError(f"loss_with_call must be numeric for call {call_id!r}")
        gain = loss_without - loss_with
        normalized_gain = round(gain / prediction_tokens, 8)
        accepted = bool(parseable) and normalized_gain >= threshold
        diagnostics.append({
            "call_id": call_id,
            "normalized_gain": normalized_gain,
            "accepted": accepted
        })
        if accepted:
            accepted_call_ids.append(call_id)
    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics
    }
